goals.ncin:
¬∀ {G : Type u} [inst : Group G] [inst_1 : Fintype G] {p m : ℕ} {H : Subgroup G}
    [inst_2 : Fintype ↥H],
    Nat.Prime p ∧ ¬p ∣ m ∧ card G = p * m ∧ H.Normal ∧ card ↥H = p → (H.Characteristic ↔ H.Characteristic)

goals.nhyp:
