    [inst_2 : Fintype ↥K],
    Nat.Prime p ∧ card G = p ^ n ∧ card ↥K = p ^ (n - 1) ↔ Nat.Prime p ∧ card G = p ^ n ∧ card ↥K = p ^ (n - 1)

